import React, { useEffect } from 'react';
import { config, tvmConfig } from '../config/config';

// 한글 레이블 매핑
export const labelMap = {
  // 인터넷 에센스 (1G)
  internet_essence_tvbiz_mult_5year: '인터넷 에센스(1G) 5년 ',
  internet_essence_tvbiz_mult_4year: '인터넷 에센스(1G) 4년 ',
  internet_essence_tvbiz_mult_3year: '인터넷 에센스(1G) 3년 ',
  internet_essence_tvbiz_mult_2year: '인터넷 에센스(1G) 2년 ',
  internet_essence_tvbiz_mult_1year: '인터넷 에센스(1G) 1년 ',
  // 인터넷 베이직 (500M)
  internet_basic_tvbiz_mult_5year: '인터넷 베이직(500M) 5년 ',
  internet_basic_tvbiz_mult_4year: '인터넷 베이직(500M) 4년 ',
  internet_basic_tvbiz_mult_3year: '인터넷 베이직(500M) 3년 ',
  internet_basic_tvbiz_mult_2year: '인터넷 베이직(500M) 2년 ',
  internet_basic_tvbiz_mult_1year: '인터넷 베이직(500M) 1년 ',
  // 인터넷 슬림 (100M)
  internet_slim_tvbiz_mult_5year: '인터넷 슬림(100M) 5년 ',
  internet_slim_tvbiz_mult_4year: '인터넷 슬림(100M) 4년 ',
  internet_slim_tvbiz_mult_3year: '인터넷 슬림(100M) 3년 ',
  internet_slim_tvbiz_mult_2year: '인터넷 슬림(100M) 2년 ',
  internet_slim_tvbiz_mult_1year: '인터넷 슬림(100M) 1년 ',
  // 지니TV 에센스 (266채널)
  tv_ginie_essence_tvbiz_mult_5year: '지니TV 에센스(266채널) 5년 ',
  tv_ginie_essence_tvbiz_mult_4year: '지니TV 에센스(266채널) 4년 ',
  tv_ginie_essence_tvbiz_mult_3year: '지니TV 에센스(266채널) 3년 ',
  tv_ginie_essence_tvbiz_mult_2year: '지니TV 에센스(266채널) 2년 ',
  tv_ginie_essence_tvbiz_mult_1year: '지니TV 에센스(266채널) 1년 ',
  // 지니TV 라이트 (240채널)
  tv_ginie_lite_tvbiz_mult_5year: '지니TV 라이트(240채널) 5년 ',
  tv_ginie_lite_tvbiz_mult_4year: '지니TV 라이트(240채널) 4년 ',
  tv_ginie_lite_tvbiz_mult_3year: '지니TV 라이트(240채널) 3년 ',
  tv_ginie_lite_tvbiz_mult_2year: '지니TV 라이트(240채널) 2년 ',
  tv_ginie_lite_tvbiz_mult_1year: '지니TV 라이트(240채널) 1년 ',
  // 지니TV 베이직 (236채널)
  tv_ginie_basic_tvbiz_mult_5year: '지니TV 베이직(236채널) 5년 ',
  tv_ginie_basic_tvbiz_mult_4year: '지니TV 베이직(236채널) 4년 ',
  tv_ginie_basic_tvbiz_mult_3year: '지니TV 베이직(236채널) 3년 ',
  tv_ginie_basic_tvbiz_mult_2year: '지니TV 베이직(236채널) 2년 ',
  tv_ginie_basic_tvbiz_mult_1year: '지니TV 베이직(236채널) 1년 ',
  // 지니TV 심플 (220채널)
  tv_ginie_slim_tvbiz_mult_5year: '지니TV 심플(220채널) 5년 ',
  tv_ginie_slim_tvbiz_mult_4year: '지니TV 심플(220채널) 4년 ',
  tv_ginie_slim_tvbiz_mult_3year: '지니TV 심플(220채널) 3년 ',
  tv_ginie_slim_tvbiz_mult_2year: '지니TV 심플(220채널) 2년 ',
  tv_ginie_slim_tvbiz_mult_1year: '지니TV 심플(220채널) 1년 '
};

export default function TVBizForm({ selections, onChange, onCalculate }) {
  const {
    agreementPeriod,
    internetPlan,
    tvPlan,
    totalRooms,
    settopCount,
    adultSubscribe,
    stbModel
  } = selections;

  const suffixMap = {
    '5년': '5year',
    '4년': '4year',
    '3년': '3year',
    '2년': '2year',
    '1년': '1year'
  };
  const yearSuffix = suffixMap[agreementPeriod] || '';

  // totalRooms 변경 시 settopCount 초기화
  useEffect(() => {
    if (totalRooms && !settopCount) onChange('settopCount', totalRooms);
  }, [totalRooms, settopCount, onChange]);

  const agreementOptions = ['5년', '4년', '3년', '2년', '1년'];
  const internetKeys = Object.keys(config).filter(
    k => k.startsWith('internet_') && k.includes(yearSuffix)
  );
  const tvKeys = Object.keys(config).filter(
    k => k.startsWith('tv_') && k.includes(yearSuffix)
  );

  // 셋탑박스 선택 옵션
  const stbOptions = Object.entries(tvmConfig.setTopBoxes_vat_out || {}).map(
    ([id, { label }]) => ({ id, label })
  );

  return (
    <>
       {/* 주의 문구 */}
    <p className="mt-2 text-base font-bold text-red-500">주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.</p>
      {/* 1행: 약정 / 인터넷 / TV */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">약정</h3>
          <select
            className="w-full border rounded p-2"
            value={agreementPeriod}
            onChange={e => onChange('agreementPeriod', e.target.value)}
          >
            <option value="">선택하세요</option>
            {agreementOptions.map(y => (
              <option key={y} value={y}>{y}</option>
            ))}
          </select>
        </div>
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">인터넷</h3>
          <select
            className="w-full border rounded p-2"
            value={internetPlan}
            onChange={e => onChange('internetPlan', e.target.value)}
            disabled={!yearSuffix}
          >
            <option value="">약정 선택 후</option>
            {internetKeys.map(k => (
              <option key={k} value={k}>{labelMap[k]}</option>
            ))}
          </select>
        </div>
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">TV</h3>
          <select
            className="w-full border rounded p-2"
            value={tvPlan}
            onChange={e => onChange('tvPlan', e.target.value)}
            disabled={!yearSuffix}
          >
            <option value="">약정 선택 후</option>
            {tvKeys.map(k => (
              <option key={k} value={k}>{labelMap[k]}</option>
            ))}
          </select>
        </div>
      </div>

      {/* 2행: TV회선 / 셋탑박스 수량 / 성인채널 구독 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">TV회선</h3>
          <input
            type="number"
            className="w-full border rounded p-2"
            value={totalRooms}
            onChange={e => onChange('totalRooms', e.target.value)}
            placeholder="입력하세요"
            disabled={!yearSuffix}
          />
        </div>
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">셋탑 박스 수량</h3>
          <input
            type="number"
            className="w-full border rounded p-2"
            value={settopCount}
            onChange={e => onChange('settopCount', e.target.value)}
            placeholder="입력하세요"
            disabled={!yearSuffix}
          />
        </div>
        <div className="border rounded p-4">
          <h3 className="font-semibold mb-2">성인채널 구독</h3>
          <select
            className="w-full border rounded p-2"
            value={adultSubscribe || ''}
            onChange={e => onChange('adultSubscribe', e.target.value)}
            disabled={!yearSuffix}
          >
            <option value="">선택하세요</option>
            <option value="yes">구독</option>
            <option value="no">미구독</option>
          </select>
        </div>
      </div>

      {/* 3행: 셋탑박스 모델 선택 */}
      <div className="border rounded p-4 mb-6">
        <h3 className="font-semibold mb-2">셋탑박스 선택</h3>
        <select
          className="w-full border rounded p-2"
          value={selections.stbModel || ''}
          onChange={e => onChange('stbModel', e.target.value)}
          disabled={!yearSuffix}
        >
          <option value="">-- 셋탑박스 선택 --</option>
          {stbOptions.map(({ id, label }) => (
            <option key={id} value={id}>{label}</option>
          ))}
        </select>
      </div>

      {/* 계산 버튼 */}
      <div>
        <button
          onClick={onCalculate}
          className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition"
          disabled={!agreementPeriod || !internetPlan || !tvPlan}
        >
          계산하기
        </button>
      </div>
    </>
  );
}
